// Decode only the QR format generated by BareFit. Never execute arbitrary QR URLs.
export function parsePairQr(raw) {
  if (typeof raw !== 'string' || raw.length > 2048) throw Error('קוד QR לא תקין');
  let url;
  try { url = new URL(raw.trim()); } catch { throw Error('זה אינו קוד חיבור של BareFit'); }
  const data = new URLSearchParams(url.hash.slice(1));
  const room = data.get('room'), code = data.get('code');
  const qrToken = data.get('qr');
  if (!['http:','https:'].includes(url.protocol) || url.username || url.password ||
      url.pathname !== '/' || url.searchParams.get('mode') !== 'coach' ||
      !/^[a-f0-9]{10}$/.test(room || '') || !/^[a-f0-9]{8}$/.test(code || ''))
    throw Error('זה אינו קוד חיבור של BareFit. סרקו את הקוד שמופיע במסך האימון.');
  if (qrToken !== null && !/^[a-f0-9]{64}$/.test(qrToken)) throw Error('קישור החיבור אינו תקין. סרקו קוד חדש מהמסך.');
  const studioId=url.searchParams.get('studio');
  if(studioId!==null&&!['1','2'].includes(studioId))throw Error('קוד הסטודיו אינו תקין');
  return {base:url.origin,room,code,studioId:studioId||'1',...(qrToken ? {qrToken} : {})};
}
export function pairLink(base, code, studioId='1') {
  const url = new URL('/', base);
  url.search = `?mode=coach&v=auto-pair-6&studio=${studioId}`;
  url.hash = new URLSearchParams({room:code.room,code:code.code,...(code.qrToken ? {qr:code.qrToken} : {})}).toString();
  return url.href;
}
